import torch
import torch.nn as nn
# Quick validation with tiny tensors
conv = nn.ConvTranspose2d(4, 8, 3, stride=2, padding=1, output_padding=1)
x = torch.randn(1, 4, 16, 16)
w = conv.weight
b = conv.bias
ref = conv(x)

H_out = ref.shape[2]
W_out = ref.shape[3]
manual = torch.zeros(1, 8, H_out, W_out)
for oc in range(8):
    for oh in range(H_out):
        for ow in range(W_out):
            accum = 0.0
            for ic in range(4):
                for ky in range(3):
                    ih_base = oh + 1 - ky
                    if ih_base % 2 == 0:
                        ih = ih_base // 2
                        if 0 <= ih < 16:
                            for kx in range(3):
                                iw_base = ow + 1 - kx
                                if iw_base % 2 == 0:
                                    iw = iw_base // 2
                                    if 0 <= iw < 16:
                                        accum += x[0,ic,ih,iw].item() * w[ic,oc,ky,kx].item()
            accum += b[oc].item()
            manual[0,oc,oh,ow] = accum
diff = (ref - manual).abs().max().item()
print(f'Shape: {ref.shape}, Max diff: {diff}, Match: {diff < 1e-5}')
"
", "justification": "Quick verify conv transpose formula with small tensors"}

